instrument multiplexing_spectrometer_channel {
    // Instrument parameters
    real lam = 4.05; // Wavelength in Angstroms
    real A1 = 37.14; // Angle in degrees
    real A2 = 74.28; // Angle in degrees

    // Source
    Source_simple src(
        yheight = 0.12,
        xwidth = 0.03,
        dist = 1.0,
        focus_xw = 0.03,
        focus_yh = 0.12,
        lambda0 = lam,
        dlambda = 0.4,
        flux = 1000000000000.0
    ) AT (0, 0, 0) RELATIVE ABSOLUTE ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Guide
    Guide guide(
        w1 = 0.03,
        h1 = 0.12,
        w2 = 0.03,
        h2 = 0.12,
        l = 20.0,
        m = 2.0
    ) AT (0, 0, 1.0) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Monochromator arm
    Arm mono_arm AT (0, 0, 21.2) RELATIVE src ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Monochromator
    Monochromator_flat mono(
        zwidth = 0.15,
        yheight = 0.12,
        mosaich = 40,
        mosaicv = 40,
        DM = 3.355
    ) AT (0, 0, 0) RELATIVE mono_arm ROTATED (0, A1, 0) RELATIVE mono_arm;

    // Out arm
    Arm out_arm AT (0, 0, 0) RELATIVE mono_arm ROTATED (0, A2, 0) RELATIVE mono_arm;

    // Wavelength monitor after monochromator
    L_monitor mono_lam(
        nL = 200,
        filename = "mono_lam.dat",
        xwidth = 0.06,
        yheight = 0.12,
        Lmin = lam - 1,
        Lmax = lam + 1,
        restore_neutron = 1
    ) AT (0, 0, 0.8) RELATIVE out_arm ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Sample position monitor
    PSD_monitor sample_psd(
        nx = 60,
        ny = 60,
        filename = "sample_psd.dat",
        xwidth = 0.05,
        yheight = 0.1,
        restore_neutron = 1
    ) AT (0, 0, 1.5) RELATIVE out_arm ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Analyzer arm
    Arm ana_arm AT (0, 0, 2.5) RELATIVE out_arm ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Analyzer
    Monochromator_flat ana(
        zwidth = 0.12,
        yheight = 0.12,
        mosaich = 40,
        mosaicv = 40,
        DM = 3.355
    ) AT (0, 0, 0) RELATIVE ana_arm ROTATED (0, -A1, 0) RELATIVE ana_arm;

    // Detector arm
    Arm det_arm AT (0, 0, 0) RELATIVE ana_arm ROTATED (0, -A2, 0) RELATIVE ana_arm;

    // Detector monitor
    PSD_monitor det(
        nx = 60,
        ny = 60,
        filename = "det.dat",
        xwidth = 0.06,
        yheight = 0.12,
        restore_neutron = 1
    ) AT (0, 0, 0.8) RELATIVE det_arm ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

    // Define the run parameters
    DEFINE/CONSTANT ncount = 1e6;
    DEFINE/CONSTANT seed = 123456;

    // Run the simulation
    RUN {
        src.ncount = ncount;
        src.seed = seed;
    }

    // Output the results
    OUTPUT {
        // Integrated intensity on each monitor
        // Format: monitor_name, intensity, error, event_count
        "Integrated intensity on mono_lam: " + mono_lam.intensity + " ± " + mono_lam.error + " (events: " + mono_lam.count + ")";
        "Integrated intensity on sample_psd: " + sample_psd.intensity + " ± " + sample_psd.error + " (events: " + sample_psd.count + ")";
        "Integrated intensity on det: " + det.intensity + " ± " + det.error + " (events: " + det.count + ")";
    }
}
